typedef struct {
    uint8_t w[3]; /* TW_* of osc 1..3 */
    uint8_t flags; /* TRIO_RING | TRIO_SYNC */
    int16_t g[3]; /* Q15 levels (0: silent; osc 3 still runs for RING) */
} trio_set_t;
