/* Sympathetic strings after Rings (Emilie Gillet, MIT; rings/dsp/part.cc RenderStringVoice and
 * string.cc), in fixed point, for the PHYS engine's SYMP model (eng_phys.c). The plucked main string is
 * phys_dsp.c's (DaisySP's String, itself from Rings); its output drives a few more strings tuned to other
 * notes, which ring on by resonance. As in Rings: the sympathetic strings get the main string's output
 * scaled down as their only input, a brightness of b (2 - b) twice (brighter than the main string's) and a
 * long decay (RT60 0.07 s 2^(8 d (2 - d)) for a damping d above the main string's: 0.25 + 0.72 DAMP, 0.8 s
 * .. 11 s; Rings: 0.7 + 0.27), and the voice's output is the sum of all the strings.
 *
 * Departures: three sympathetic strings (Rings: up to seven, with detuned copies) on chords picked by the
 * caller (Rings: an interpolated table, or its quantised chord table); each is a plain delay loop (a
 * 256-sample line of 16-bit values (Q12), linear interpolation, a two-tap FIR loop filter b x + (1 - b) x', the
 * loop gain of its RT60) instead of Rings' String with its dispersion, IIR damping filter and LFO-moved
 * pickup position; a string whose period exceeds the line sounds an octave (or two) higher. */
typedef struct { /* coefficients (px_symp_block; kept while unchanged) */
    uint32_t d[3]; /* read delay, whole samples */
    int32_t h[3][3]; /* the loop: taps d, d + 1, d + 2 (Q24): the loop gain, the
                                                          * FIR b x + (1 - b) x' and the linear interpolation in one */
    int32_t cin; /* the main string into them, Q16 */
    uint32_t on; /* strings on (bits) */
} px_symp_cf_t;
typedef struct {
    px_string_t s; /* the main string (phys_dsp.c) */
    int16_t line[3][256]; /* the sympathetic strings, Q12 (+-8) */
    int32_t dcx, dcy, dce; /* the DC blocker on their input (Rings: part.cc), its
                                                          * rounding error fed back (as DcBlock) */
    uint32_t wp;
    int32_t yl; /* the strings' last sum (half rate), Q12 */
    int32_t key[6]; /* the inputs cf was worked out for */
    px_symp_cf_t cf;
} px_symp_t;
/* the coefficients, when an input changed. f[k]: the sympathetic strings' frequencies (cycles Q32, 0 = off); brightness, damping, amount Q16 0..1 */
static void px_symp_block(px_symp_t *Y, const uint32_t *f, int32_t brightness, int32_t damping,
                                                    int32_t amount)
{
    px_symp_cf_t *B = &Y->cf;
    int32_t b = px_m(brightness, 131072 - brightness, 16), dd = 16384 + px_m(damping, 47186, 16), lfd, k8;
    uint32_t k;
    if (Y->key[0] == (int32_t)f[0] && Y->key[1] == (int32_t)f[1] && Y->key[2] == (int32_t)f[2] && Y->key[3] == brightness &&
        Y->key[4] == damping && Y->key[5] == amount)
        return;
    Y->key[0] = (int32_t)f[0];
    Y->key[1] = (int32_t)f[1];
    Y->key[2] = (int32_t)f[2];
    Y->key[3] = brightness;
    Y->key[4] = damping;
    Y->key[5] = amount;
    b = px_m(b, 131072 - b, 16); /* b (2 - b), twice */
    b = 32768 + (b >> 1); /* the FIR: 0.5 .. 1 */
    lfd = px_m(dd, 131072 - dd, 16);
    k8 = (int32_t)px_exp2(-8 * lfd); /* 2^(-8 lfd): 0.07 s / RT60 */
    B->cin = amount >> 4; /* at most 1 / 16 (of a pair: 1 / 8) */
    B->on = 0;
    for (k = 0; k < 3; k++) {
        uint32_t p, e;
        int32_t c, fr;
        if (f[k] < 65536u)
            continue;
        p = f[k] >= 0x40000000u ? 0 : (uint32_t)(((uint64_t)1 << 47) / f[k]); /* period, half-rate steps Q16 */
        while (p > (uint32_t)(256 - 4) << 16) /* fold up an octave */
            p >>= 1;
        p -= (uint32_t)(65536 - b); /* less the FIR's delay */
        if (p < 2u << 16)
            continue;
        /* gain per period 2^(-10 period / RT60) = 2^(-10 p / (1543.5 steps) * k8) */
        e = (uint32_t)(((((uint64_t)p * 27826874u) >> 32) * (uint32_t)k8) >> 16); /* octaves, Q16 (10 / 1543.5: Q32) */
        c = e > 15u << 16 ? 0 : (int32_t)(px_exp2(-(int32_t)e) << 8); /* Q24 */
        if (c > 16775500)
            c = 16775500; /* 0.9999 */
        fr = (int32_t)(p & 0xFFFFu);
        B->d[k] = p >> 16;
        B->h[k][0] = px_m(c, px_m(b, 65536 - fr, 16), 16);
        B->h[k][1] = px_m(c, px_m(b, fr, 16) + px_m(65536 - b, 65536 - fr, 16), 16);
        B->h[k][2] = px_m(c, px_m(65536 - b, fr, 16), 16);
        B->on |= 1u << k;
    }
}
/* n (<= 32, even) samples: out[i] = in[i] (the main string) + the sympathetic strings it drives. They run at half
 * the rate (the input summed over each pair, the output interpolated linearly), a string at a time over the
 * block (its line is read at least a step back: the order is kept). The loop truncates towards 0: rounding
 * leaves a dead band in which a small value never decays (a limit cycle), a floor a bias that rings at DC
 * (a comb resonates there too) */
static void px_symp_run(px_symp_t *Y, const int32_t *in, int32_t *out, uint32_t n)
{
    const px_symp_cf_t *B = &Y->cf;
    uint32_t i, k, m;
    int32_t dcx = Y->dcx, dcy = Y->dcy, dce = Y->dce, x[16], acc[16], yl = Y->yl;
    if (n > 32u)
        n = 32u;
    m = n >> 1;
    for (i = 0; i < m; i++) { /* their input: the string, a pair summed, less its DC */
        int32_t v = px_m(in[2 * i] + in[2 * i + 1], B->cin, 16); /* (~10 Hz), Q12 */
        int64_t a = (int64_t)1070617000 * dcy + dce;
        dcy = v - dcx + (int32_t)(a >> 30);
        dce = (int32_t)(a & 0x3FFFFFFF);
        dcx = v;
        x[i] = (dcy + 128) >> 8;
        acc[i] = 0;
    }
    for (k = 0; k < 3; k++) {
        int16_t *l = Y->line[k];
        uint32_t wp = Y->wp, d = B->d[k];
        int32_t h0 = B->h[k][0], h1 = B->h[k][1], h2 = B->h[k][2];
        if (!(B->on >> k & 1u))
            continue;
        for (i = 0; i < m; i++) {
            uint32_t t = wp + d;
            int64_t s = (int64_t)h0 * l[t & (256 - 1)] + (int64_t)h1 * l[(t + 1u) & (256 - 1)] +
                        (int64_t)h2 * l[(t + 2u) & (256 - 1)];
            int32_t y = px_clamp((int32_t)((s + ((s >> 63) & 0xFFFFFF)) >> 24) + x[i], -32767, 32767);
            l[wp] = (int16_t)y;
            acc[i] += y;
            wp = (wp - 1u) & (256 - 1);
        }
    }
    for (i = 0; i < m; i++) {
        out[2 * i] = in[2 * i] + ((yl + acc[i]) << 7);
        out[2 * i + 1] = in[2 * i + 1] + (acc[i] << 8);
        yl = acc[i];
    }
    if (n & 1u)
        out[n - 1u] = in[n - 1u] + (yl << 8);
    Y->wp = (Y->wp - m) & (256 - 1);
    Y->yl = yl;
    Y->dcx = dcx;
    Y->dcy = dcy;
    Y->dce = dce;
}
enum { PM_MODAL, PM_STRING, PM_MEMB, PM_SYMP, PM_COUNT };
/* output: model 1.0 -> this (VOICE_FS scale), then a soft knee; per model (a strike of all the modes in
 * phase peaks high but is short) */
static const int32_t PHYS_GAIN[PM_COUNT] = {28000, 12000, 90000, 12000};
typedef struct {
    uint8_t model; /* PM_* the state belongs to */
    union {
        px_modal_t m; /* MODAL, MEMB */
        px_string_t s;
        px_symp_t y;
    } u;
} phys_slot_t;
_Static_assert((sizeof(phys_slot_t) * 3) <= 12888u, "PHYS" " state over ENG_MEM_PART"); /* (it sets ENG_MEM_PART) */
static const char *const N_PHYS_MODEL[] = {"MODAL", "STRNG", "MEMB", "SYMP"};
static const char *const N_PHYS_CHORD[] = {"OCT", "5TH", "4TH", "MAJ", "MIN", "SUS", "7TH", "ROOT", 0};
/* per model: STRC .. EXC under their own names (phys_desc; range and default as edit[], 0 = edit[]) */
static const param_desc_t PHYS_D_HARM = {"HARM", F_PCT, 0, 127, 64, 0, 0};
static const param_desc_t PHYS_D_BEND = {"BEND", F_PCT, 0, 127, 0, 0, 0};
static const param_desc_t PHYS_D_CHRD = {"CHRD", F_INT, 0, 127, 64, N_PHYS_CHORD, 0};
static const param_desc_t PHYS_D_SYMP = {"SYMP", F_PCT, 0, 127, 20, 0, 0};
static const param_desc_t PHYS_D_BUZZ = {"BUZZ", F_PCT, 0, 127, 0, 0, 0};
static const param_desc_t *const PHYS_DESC[PM_COUNT][8] = {
    [PM_MEMB] = {0, &PHYS_D_HARM, 0, 0, 0, 0, &PHYS_D_BEND, 0},
    [PM_SYMP] = {0, &PHYS_D_CHRD, 0, 0, &PHYS_D_SYMP, 0, &PHYS_D_BUZZ, 0},
};
static const param_desc_t *phys_desc(const track_t *t, uint32_t k)
{
    return k < 8u ? PHYS_DESC[(uint32_t)t->p[P_E0] % PM_COUNT][k] : 0;
}
/* SYMP: the sympathetic strings above the note, cents (CHRD's names) */
static const int16_t PHYS_CHORDS[7][3] = {
    {-1200, 1200, 2400}, {700, 1200, 1900}, {500, 1200, 1700}, {400, 700, 1200},
    {300, 700, 1200}, {200, 700, 1400}, {400, 700, 1000},
};
static const int8_t PHYS_DETUNE[3] = {1, -1, 0}; /* 1/16 semitone (6 cents): the strings beat a little */
/* a project or user preset saved before 1.0 (MODEL 2 was DUST): its E values as today's */
static void phys_legacy(int16_t *e)
{
    if (e[0] == 2) { /* DUST -> MODAL bowed (random hits into resonators) */
        e[0] = PM_MODAL;
        e[6] = 64;
    }
}
static phys_slot_t *phys_slot_of(track_t *t, voice_t *v)
{
    uint32_t i;
    if (t < &PKV(2)[0] || t >= &PKV(2)[4])
        return 0;
    i = (uint32_t)(v - t->v);
    return i < 3 ? (phys_slot_t *)((void *)PKV(6)[t - PKV(2)].b) + i : 0;
}
/* a clean state for model md */
static void phys_reset(phys_slot_t *S, uint32_t md, uint32_t seed)
{
    uint32_t i, *w = (uint32_t *)&S->u;
    for (i = 0; i < sizeof S->u / 4u; i++)
        w[i] = 0;
    S->model = (uint8_t)md;
    seed |= 1u;
    switch (md) {
    case PM_STRING:
    case PM_SYMP: /* (the main string is the union's px_string_t) */
        S->u.s.rng = seed;
        S->u.s.src = 1u << 30;
        break;
    default:
        S->u.m.rng = seed;
        break;
    }
}
static void phys_note_on(track_t *t, voice_t *v)
{
    phys_slot_t *S = phys_slot_of(t, v);
    uint32_t md = (uint32_t)t->p[P_E0] % PM_COUNT;
    if (!S)
        return;
    if ((!v->env && !v->env_out) || S->model != md) /* a fresh voice (not a retrigger): from rest */
        phys_reset(S, md, rng());
    switch (md) {
    case PM_MODAL:
    case PM_MEMB:
        S->u.m.trig = 1; /* a retrigger strikes the ringing body again */
        break;
    default: /* STRNG, SYMP */
        S->u.s.trig = 1;
        break;
    }
}
/* SYMP: the sympathetic strings' pitches (cycles Q32) by CHRD: a chord above the note, or ROOT */
static void phys_symp_pitches(const track_t *t, const vmod_t *m, uint32_t *f)
{
    uint32_t c = (uint32_t)t->p[P_E1] >> 4, k; /* 0..7 */
    for (k = 0; k < 3; k++) {
        int32_t p16 = PHYS_DETUNE[k];
        p16 += c < 7u ? m->pitch16 + ((PHYS_CHORDS[c][k] * 41) >> 8) /* cents -> 1/16 semitones (0.16) */
                      : (48 + t->p[P_ROOT] + (k == 1u ? 7 : k == 2u ? 12 : 0)) * 16;
        f[k] = pitch_inc(clamp(p16, 0, 2047));
    }
}
static void phys_render(track_t *t, voice_t *v, int32_t *out, uint32_t n, const vmod_t *m)
{
    const int16_t *p = t->p;
    phys_slot_t *S = phys_slot_of(t, v);
    uint32_t md = (uint32_t)p[P_E0] % PM_COUNT, i, f0 = m->inc;
    int32_t y[32], ax[32];
    int32_t strc = p[P_E1] * 516, brit = clamp(p[P_E2] * 516 + m->cutoff * 2, 0, 65536); /* Q16 0..1 */
    int32_t damp = p[P_E3] * 516, pos = p[P_E4], exc = p[P_E7] * 258; /* exc Q15 */
    int32_t bow = p[P_E6] * 206; /* BOW: Dust at up to 0.4 (DaisySP's sustain: 1) */
    int32_t acc = clamp(p[P_E5] * v->vel * 4, 0, 65536); /* ACC at full velocity, Q16 */
    int32_t g = PHYS_GAIN[md];
    if (!S)
        return;
    if (n > 32)
        n = 32;
    if (S->model != md) /* MODEL changed under a sounding note */
        phys_reset(S, md, rng());
    switch (md) {
    case PM_MODAL: {
        px_modal_blk_t B;
        px_modal_block(&B, &S->u.m, f0, strc, brit, damp, acc, pos * 129, bow); /* pos 0..1/4 */
        px_modal_run(&B, &S->u.m, y, ax, n);
        break;
    }
    case PM_MEMB: {
        px_modal_blk_t B;
        px_memb_block(&B, &S->u.m, f0, strc, brit, damp, acc, pos * 516, p[P_E6] * 6192); /* BEND 0..12 st */
        px_modal_run(&B, &S->u.m, y, ax, n);
        break;
    }
    case PM_STRING: {
        px_string_blk_t B;
        px_string_block(&B, &S->u.s, f0, strc, brit, damp, acc, bow, pos * 516); /* 0..1/2 period */
        px_string_excite(&B, &S->u.s, ax, n);
        px_string_run(&B, &S->u.s, ax, y, n);
        break;
    }
    default: { /* SYMP */
        px_string_blk_t B;
        uint32_t f[3];
        phys_symp_pitches(t, m, f);
        px_string_block(&B, &S->u.y.s, f0, 16384 - p[P_E6] * 129, brit, damp, acc, 0, 0); /* BUZZ: STRC 0.25 .. 0 */
        px_string_excite(&B, &S->u.y.s, ax, n);
        px_string_run(&B, &S->u.y.s, ax, y, n);
        px_symp_block(&S->u.y, f, brit, damp, pos * 516);
        px_symp_run(&S->u.y, y, y, n);
        break;
    }
    }
    for (i = 0; i < n; i++) {
        int32_t s = px_m(y[i] + px_m(ax[i], exc, 15), g, 20), a = s < 0 ? -s : s;
        if (a > 24000) { /* soft knee: only peaks saturate */
            a = 24000 + (softclip(clamp(a - 24000, 0, 1 << 20) * 2) >> 1);
            s = s < 0 ? -a : a;
        }
        out[i] += voice_amp(s, m, i) << 1;
    }
}
