enum { D_PITCH, D_OSC2, D_CTRL1, D_NOISE, D_CUT, D_AMP, D_LFO2F };
enum { U_SQR1, U_SQR2, U_SIN1, U_SIN2, U_SAW1, U_SAW2, U_MIX1, U_MIX2 }; /* SUB TYPE: -1 SQR .. -2 MIX */
