/* PHASER: the stages' coefficient a (Q14) for a break of 150 Hz * 2^(5 i / 32): a = (g - 1) / (g + 1), g = tan(pi f / fs) */
static const int16_t PH_A[33] = {
    -16038, -15998, -15955, -15906, -15853, -15793, -15727, -15653, -15572, -15481, -15381, -15270, -15147, -15012,
    -14862, -14696, -14514, -14313, -14092, -13849, -13582, -13290, -12970, -12621, -12240, -11825, -11375, -10886,
    -10356, -9784, -9166, -8500, -7783,
};
/* PHASER: the stages' coefficient at the sweep's place q (Q14) */
static int32_t ph_coef(uint32_t q)
{
    uint32_t t = pf_tri(q), i = t >> 11;
    return PH_A[i] + (((PH_A[i + 1u] - PH_A[i]) * (int32_t)(t & 2047u)) >> 11);
}
/* PHASER on one side c: x in, the stages' coefficient a (rounded: no DC creeping in through the low breaks) */
static inline int32_t ph_side(uint32_t c, int32_t x, int32_t a)
{
    int32_t xs = clamp((x + 2) >> 2, -16383, 16383), u = xs + ((PKV(86).pfb[c] * 13107 + 16384) >> 15), y = u;
    uint32_t s;
    for (s = 0; s < 4u; s++) { /* y = a (u - y1) + u1 */
        y = clamp(PKV(86).px[c][s] + ((a * (u - PKV(86).py[c][s]) + 8192) >> 14), -65535, 65535);
        PKV(86).px[c][s] = u;
        PKV(86).py[c][s] = y;
        u = y;
    }
    PKV(86).pfb[c] = clamp(y, -32767, 32767);
    u = xs + y; /* (x + y) / 2 * 0.9, x 4 (>> 2 above): (x + y) * 1.8 */
    return pf_mix(x, u + mulq16(u, 52429u), PKV(86).pw);
}
/* after FLANGER, while held or fading: PHASER (noinline, as FLANGER). The coefficients a block at a time (at its
 * middle: 2.9 ms at most, the sweep moves 1 % in frequency meanwhile) */
static void perf_phaser(int32_t *bl, int32_t *br, uint32_t n)
{
    uint32_t i, c, inc, q = perf_lfo(8u, n, &inc) + (n >> 1) * inc;
    int32_t tw = PKV(86).act & (1u << (PF_PHS)) ? perf_mod_depth() : 0, *const b[2] = {bl, br};
    int32_t a[2] = {ph_coef(q), ph_coef(q - 0x40000000u)}; /* (the right a quarter of the sweep behind) */
    if (!PKV(86).pw) { /* starting: the stages from rest */
        memset(PKV(86).px, 0, sizeof PKV(86).px);
        memset(PKV(86).py, 0, sizeof PKV(86).py);
        PKV(86).pfb[0] = PKV(86).pfb[1] = 0;
    }
    for (i = 0; i < n; i++) {
        PKV(86).pw += clamp(tw - PKV(86).pw, -(32768 / (1 << 7)), (32768 / (1 << 7)));
        for (c = 0; c < 2u; c++)
            b[c][i] = ph_side(c, b[c][i], a[c]);
    }
}
/* after the master level: the buffer effect, LPF, HPF, CRUSH on l / r (stereo, Q15) */
static void perf_block(int32_t *bl, int32_t *br, uint32_t n)
{
    uint32_t i, a = PKV(86).act0, sh, hold;
    int32_t c = PKV(78)[1], lt, ht, ct;
    if (c)
        PKV(86).cc = c;
    ct = c ? 32768 : 0;
    sh = 4u + (uint32_t)PKV(86).cc * 7u / 100u;
    hold = sh - 3u;
    if (PKV(86).split)
        perf_switch(a);
    PKV(86).hfb += clamp(PKV(78)[3] * 269 - PKV(86).hfb, -512, 512); /* OCT UP / DN's shimmer glides (~40 ms) */
    for (i = 0; i < n; i++) {
        int32_t l = bl[i], r = br[i];
        if (i == PKV(86).split) {
            a = PKV(86).act;
            perf_switch(a);
        }
        if (PKV(86).mode != BM_NONE)
            perf_buf(&l, &r);
        lt = (a & (1u << (PF_LPF))) || PKV(78)[0] < 0 || PKV(86).lc < (63 << 8) ? 32768 : 0;
        PKV(86).la += clamp(lt - PKV(86).la, -(32768 / (1 << 7)), (32768 / (1 << 7)));
        if (PKV(86).la) {
            int32_t fl = pf_svf(clamp(l >> 2, -32767, 32767), &PKV(86).lz[0], PKV(86).lk, 0) << 2;
            int32_t fr = pf_svf(clamp(r >> 2, -32767, 32767), &PKV(86).lz[2], PKV(86).lk, 0) << 2;
            l = pf_mix(l, fl, PKV(86).la);
            r = pf_mix(r, fr, PKV(86).la);
        } else {
            PKV(86).lz[0] = PKV(86).lz[1] = PKV(86).lz[2] = PKV(86).lz[3] = 0;
        }
        ht = (a & (1u << (PF_HPF))) || PKV(78)[0] > 0 || PKV(86).hc > 0 ? 32768 : 0;
        PKV(86).ha += clamp(ht - PKV(86).ha, -(32768 / (1 << 7)), (32768 / (1 << 7)));
        if (PKV(86).ha) {
            int32_t fl = pf_svf(clamp(l >> 2, -32767, 32767), &PKV(86).hz[0], PKV(86).hk, 1) << 2;
            int32_t fr = pf_svf(clamp(r >> 2, -32767, 32767), &PKV(86).hz[2], PKV(86).hk, 1) << 2;
            l = pf_mix(l, fl, PKV(86).ha);
            r = pf_mix(r, fr, PKV(86).ha);
        } else {
            PKV(86).hz[0] = PKV(86).hz[1] = PKV(86).hz[2] = PKV(86).hz[3] = 0;
        }
        { /* CRUSH: fewer bits, a held sample (KNOB 2) */
            PKV(86).cw += clamp(ct - PKV(86).cw, -(32768 / (1 << 7)), (32768 / (1 << 7)));
            if (PKV(86).cw) {
                if (++PKV(86).cn >= hold) {
                    PKV(86).cn = 0;
                    PKV(86).chl = ((l >> sh) << sh) + (1 << (sh - 1u));
                    PKV(86).chr = ((r >> sh) << sh) + (1 << (sh - 1u));
                }
                l = pf_mix(l, PKV(86).chl, PKV(86).cw);
                r = pf_mix(r, PKV(86).chr, PKV(86).cw);
            }
        }
        bl[i] = l;
        br[i] = r;
    }
    if ((PKV(86).act & (1u << (PF_FLG))) || PKV(86).fw || PKV(86).fn)
        perf_flanger(bl, br, n);
    if ((PKV(86).act & (1u << (PF_PHS))) || PKV(86).pw)
        perf_phaser(bl, br, n);
    PKV(86).busy = PKV(86).act || PKV(86).mode != BM_NONE || PKV(86).w || PKV(86).la || PKV(86).ha || PKV(86).cw || PKV(86).td || PKV(86).mute || PKV(86).fw || PKV(86).pw || PKV(86).thr ||
              PKV(86).fn || PKV(78)[0] || PKV(78)[1] || PKV(78)[2];
}
