enum { AG_NENGINES = 14, AG_CTL = 32 };
static void ag_init(void)
{
    uint32_t k;
    
    host_tracks_init();
    for (k = 1; k < 4; k++)
        PKV(2)[k].p[P_MUTE] = 1; /* the plugin plays part 1 */
    PKV(3).sel = 0;
}
static void ag_kill(void)
{
    uint32_t i;
    track_t *t = &PKV(2)[0];
    trk_all_off(t);
    for (i = 0; i < 8; i++) {
        t->v[i].active = t->v[i].gate = 0;
        t->v[i].stage = 0;
        t->v[i].env = t->v[i].env_out = 0;
    }
}
static void ag_sound(uint32_t e, uint32_t s)
{
    ag_kill();
    host_preset(&PKV(2)[0], e, s);
}
static const char *ag_own_name(uint32_t e, uint32_t s, uint32_t *count)
{
    (void)e; (void)s;
    *count = 0;
    return 0;
}
static int32_t ag_getp(uint32_t id) { return PKV(2)[0].p[id]; }
static void ag_setp(uint32_t id, int32_t v)
{
    const param_desc_t *d = &TP[id];
    PKV(2)[0].p[id] = (int16_t)(v < d->min ? d->min : v > d->max ? d->max : v);
}
static void ag_sete(uint32_t k, int32_t v)
{
    const param_desc_t *d = &ENGINES[PKV(2)[0].engine]->edit[k];
    PKV(2)[0].p[P_E0 + k] = (int16_t)(v < d->min ? d->min : v > d->max ? d->max : v);
}
static void ag_setg(uint32_t id, int32_t v)
{
    const param_desc_t *d = &GP[id];
    PKV(3).g[id] = (int16_t)(v < d->min ? d->min : v > d->max ? d->max : v);
}
static void ag_note_on(uint32_t n, uint32_t vel) { trk_note_on(&PKV(2)[0], n, vel); }
static void ag_note_off(uint32_t n) { trk_note_off(&PKV(2)[0], n); }
static void ag_all_off(void) { trk_all_off(&PKV(2)[0]); }
static void ag_bend(int32_t q8) { PKV(40)[0] = (q8); }
static void ag_render(int32_t *o, uint32_t n) { mix_block(o, n); }
static void ag_format(uint32_t e, uint32_t k, int32_t v, char *val, const char **unit)
{
    const param_desc_t *d = &ENGINES[e]->edit[k];
    *unit = 0;
    param_format(d, v, val, unit);
}

